import {getLanguage} from './i18n.js';
const c=(zh,en)=>getLanguage()==='en'?en:zh;
export const chromaRepo='https://github.com/ChefDavid0815/chroma-monitor';
export const chromaRelease=`${chromaRepo}/releases/tag/v0.1.0`;
const mosaic=(count=56)=>`<div class="cm-mosaic" aria-hidden="true">${Array.from({length:count},(_,i)=>`<i style="--i:${i};--tile:${['#fff000','#173dff','#ff273a','#00edff','#e9f2ff','#173dff'][i*7%6]}"></i>`).join('')}</div>`;
const burst='<svg viewBox="0 0 200 200" aria-hidden="true"><path d="m100 0 17 62 53-36-32 54 62 20-62 18 32 54-53-34-17 62-18-62-52 34 32-54L0 100l62-20-32-54 52 36Z"/></svg>';
const wave='<svg viewBox="0 0 360 90" preserveAspectRatio="none"><path d="M0 65H25l12-20 17 30 21-52 24 43 16-15h25l20-38 24 59 20-33 18 24h26l14-20 20 22 22-38 18 43h29"/><path d="M0 73h47l14-13 27 8 19-15 23 20h44l16-37 16 37h42l23-14 16 14h73"/></svg>';

export function chromaRig(){return `<div class="cm-rig" aria-hidden="true"><div class="cm-orbit cm-orbit--a"></div><div class="cm-orbit cm-orbit--b"></div><div class="cm-burst cm-burst--red">${burst}</div><div class="cm-monitor"><div class="cm-monitor-side"></div><div class="cm-monitor-front"><div class="cm-window-bar"><span>CHROMA / SIGNAL 001</span><b>− □ ×</b></div>${mosaic(24)}<div class="cm-screen"><div class="cm-screen-top"><span>FULL SPECTRUM</span><i>✦</i></div><div class="cm-screen-word"><span class="cm-channel-cpu">CPU</span><span class="cm-channel-gpu">GPU</span><span class="cm-channel-ram">RAM</span></div><div class="cm-screen-wave">${wave}</div><div class="cm-screen-bottom"><span>ART / SIGNAL STUDY</span><b>+ + +</b></div></div><div class="cm-monitor-foot"><span>EVERY BIT. IN COLOR.</span><i></i></div></div></div><div class="cm-floating cm-floating--frame"><div>FRAME LAB <b>↗</b></div><strong>FPS<span>FOLLOW THE FRAME.</span></strong>${mosaic(12)}</div><div class="cm-floating cm-floating--chip"><span>LOCAL FIRST</span><div class="cm-chip">C<span>01</span></div><small>HARDWARE OBSERVATORY</small></div><div class="cm-burst cm-burst--yellow">${burst}<b>✦</b></div><div class="cm-keyboard"><span>CTRL</span><span>ALT</span><span>COLOR ↗</span></div><span class="cm-coordinate cm-coordinate--a">X : 006<br>Y : 2000</span><span class="cm-coordinate cm-coordinate--b">SIGNAL REMIX<br>CHEFZC / 2026</span></div>`;}

const views={pro:{zh:'专业模式',en:'PRO',caption:['专业模式 · 英文与中文均来自实际安装版截图','PRO · Actual installed-app captures in Chinese and English']},simple:{zh:'极简模式',en:'Simple',caption:['极简模式 · 实际安装版中文界面','Simple · Actual installed application, Chinese interface']},mini:{zh:'桌面小窗',en:'Mini',caption:['桌面置顶小窗 · 真实界面，不是游戏内 OSD','Floating desktop mini view · Actual interface, not an in-game OSD']}};
function captureSrc(view){return `./assets/projects/chroma/${view==='pro'?`pro-${getLanguage()==='en'?'en':'zh'}`:view==='simple'?'simple-zh':'mini'}.png`;}
export function chromaCapture(view='pro') {return `<section class="cm-preview" data-chroma-preview="${view}"><div class="cm-preview-toolbar"><span>CHROMA.EXE <i>/</i> ${c('真实软件界面','ACTUAL APPLICATION')}</span><div role="group" aria-label="${c('选择界面截图','Choose an application screenshot')}">${Object.entries(views).map(([id,v])=>`<button type="button" data-chroma-view="${id}" aria-pressed="${id===view}">${c(v.zh,v.en)}</button>`).join('')}</div></div><figure class="cm-capture"><div class="cm-capture-mat"><img src="${captureSrc(view)}" width="${view==='mini'?410:1480}" height="${view==='mini'?351:962}" alt="${c(...views[view].caption)}" loading="lazy" decoding="async"></div><figcaption><span data-chroma-caption>${c(...views[view].caption)}</span><span>${c('截图为当时读数，不是访客硬件数据','Recorded readings, not visitor hardware data')}</span></figcaption></figure></section>`;}
export function changeChromaView(button){const host=button.closest('[data-chroma-preview]');const view=button.dataset.chromaView;if(!host||!views[view])return;host.dataset.chromaPreview=view;host.querySelectorAll('[data-chroma-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const img=host.querySelector('img');img.src=captureSrc(view);img.alt=c(...views[view].caption);img.width=view==='mini'?410:1480;img.height=view==='mini'?351:962;host.querySelector('[data-chroma-caption]').textContent=c(...views[view].caption);}
const channels={cpu:['从占用率，到核心温度。','From load to core temperatures.','逻辑线程、频率、功耗与可用传感器，给好奇心更多线索。','Logical threads, clocks, power and available sensors give curiosity more to follow.'],gpu:['让每一帧，都有迹可循。','Find the story in every frame.','GPU、显存与 PresentMon 帧分析入口。真实帧捕获取决于 ETW 权限；游戏内效果尚未验证。','GPU, VRAM and a PresentMon frame lab. Capture depends on ETW access; actual in-game behavior remains unverified.'],ram:['把这一刻，留成一份记录。','Keep a record of this moment.','内存、磁盘、网络、十分钟趋势，以及可以导出的会话记录。','Memory, disks, network, ten-minute trends and exportable session records.']};
const channelCopy=id=>`<h4>${c(channels[id][0],channels[id][1])}</h4><p>${c(channels[id][2],channels[id][3])}</p>`;
export function changeChromaChannel(button){const root=button.closest('.exhibit--chroma');if(!root)return;const id=button.dataset.chromaChannelButton;if(!channels[id])return;root.dataset.chromaChannel=id;root.querySelectorAll('[data-chroma-channel-button]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));root.querySelector('.cm-channel-copy').innerHTML=channelCopy(id);}
const actions=()=>`<div class="cm-actions"><a class="cm-primary" href="${chromaRelease}" target="_blank" rel="noopener noreferrer">${c('下载 Windows 版','Download for Windows')} <b>↓</b></a><a href="${chromaRepo}" target="_blank" rel="noopener noreferrer">GitHub <b>↗</b></a><a href="./post.html?article=chroma">${c('信号手记','Signal notes')} <b>↗</b></a><span>0.1.0 / EARLY ACCESS</span></div>`;

export function chromaCard(){return `<article class="exhibit exhibit--chroma" id="project-chroma" data-chroma-channel="cpu"><header class="cm-titlebar"><span><i></i> CHROMA.EXE <b>/</b> HARDWARE OBSERVATORY</span><span>NO. 06 <b>/</b> V0.1.0</span><span class="cm-window-controls" aria-hidden="true">− □ ×</span></header>${mosaic()}<div class="cm-hero"><div class="cm-hero-copy"><div class="cm-edition"><span>Y2K</span> SIGNAL REMIX / 001</div><h3>CHROMA<span>✦</span></h3><div class="cm-hero-slogan">EVERY BIT.<br><em>IN COLOR.</em></div><h4>${c('给电脑的心跳，调一套新颜色。','Your machine. In full color.')}</h4><p>${c('CPU、GPU、传感器与每一段性能记录。一座留在本机的硬件观测站，用像素、金属和不怕张扬的颜色，把信号变得看得见。','CPU, GPU, sensors and the story of a session. A local hardware observatory in pixels, chrome and unapologetic colour. Follow the signal.')}</p><button class="cm-detail-button" data-project="chroma">${c('打开观测站','Inside the observatory')} <b>＋</b></button></div><div class="cm-hero-stage">${chromaRig()}<span class="cm-art-note">${c('视觉装置 / 展柜不读取访客硬件','VISUAL INSTALLATION / NO VISITOR HARDWARE ACCESS')}</span></div></div><div class="cm-remix"><div class="cm-remix-label"><span>01 / COLOR CHANNEL</span><strong>${c('切换一道信号。','Remix the signal.')}</strong></div><div class="cm-channel-controls" role="group" aria-label="${c('展柜配色与功能视角','Exhibit colour and feature perspective')}">${['cpu','gpu','ram'].map((v,i)=>`<button data-chroma-channel-button="${v}" aria-pressed="${i===0}"><small>0${i+1}</small>${v.toUpperCase()}<b>↗</b></button>`).join('')}</div><div class="cm-channel-copy" aria-live="polite">${channelCopy('cpu')}</div></div><div class="cm-capabilities"><span><b>LOCAL</b>${c('读数留在本机','Your readings stay local')}</span><span><b>SIMPLE → PRO</b>${c('从一眼看懂，到继续研究','From a glance to a closer look')}</span><span><b>中 / EN</b>${c('跟随系统，也记住你的选择','Follows your system and your choice')}</span></div>${chromaCapture()}${actions()}<footer class="cm-exhibit-footer"><span>MADE OF SIGNALS. MADE WITH CURIOSITY.</span><span>CHEFZC © 2026 <b>✦</b></span></footer></article>`;}

export function chromaDetail(view='pro'){return `<div class="cm-detail"><header class="cm-detail-head"><span>SIGNAL REMIX / WINDOWS x64 / 0.1.0</span><h2 id="dialog-title">CHROMA<span>✦</span></h2><p>${c('每一道信号，都有自己的颜色。','Every signal has a colour of its own.')}</p></header>${chromaCapture(view)}<div class="cm-detail-grid"><section><span>01 / THE OBSERVATORY</span><h3>${c('想一眼看懂，也想仔细研究。','A quick glance. A closer look.')}</h3><p>${c('极简模式看 CPU / GPU 占用率和温度；专业模式展开线程、内存、磁盘、网络、传感器搜索与收藏。十分钟趋势、一小时内存会话，导出 CSV / JSON，把这一刻带走。','Simple mode shows CPU/GPU utilization and temperatures. PRO opens logical threads, memory, disks, network and searchable sensors with favorites. Ten-minute trends and one-hour in-memory sessions export to CSV / JSON.')}</p></section><section><span>02 / REAL SIGNALS</span><h3>${c('颜色可以热闹，读数必须诚实。','Expressive colour. Honest readings.')}</h3><p>${c('采集在 Windows 桌面端进行，不上传遥测。缺失读数保留为空，过期传感器会标记失效。可选 CPU 驱动与只读服务由安装向导说明；帧分析需要 ETW 权限。桌面小窗不是游戏内 OSD。','Collection runs locally in the Windows app without telemetry uploads. Missing readings remain empty and stale sensors expire. Setup explains the optional CPU driver and read-only service. Frame analysis requires ETW access. Mini view is a desktop window, not an in-game OSD.')}</p></section></div><p class="cm-boundary">${c('0.1.0 为早期版本，Windows 安装包与便携包未签名。已完成基础数据测试、构建与本机采集检查；跨硬件覆盖、真实游戏内 FPS 和长时间压力测试尚未验证。会话需在关闭前导出。','0.1.0 is early access; Windows binaries are unsigned. Basic calculation tests, build and local collection checks passed. Cross-hardware coverage, actual in-game FPS and prolonged stress testing remain unverified. Export sessions before closing.')}</p>${actions()}</div>`;}
export function chromaPostArt(){return `<div class="post-art post-art--chroma" aria-hidden="true"><div class="cm-post-top"><span>CHROMA / SIGNAL REMIX</span><span>FIELD NOTE 009</span></div>${mosaic(40)}<div class="cm-post-type">EVERY BIT.<br><em>IN COLOR.</em></div>${chromaRig()}<span class="cm-post-bottom">TURN CURIOSITY ALL THE WAY UP. <b>↗</b></span></div>`;}
export function chromaNowArt(){return `<div class="milestone-art cm-now-art" aria-hidden="true"><div class="cm-now-top"><span>CHROMA.EXE</span><b>− □ ×</b></div>${mosaic(24)}<strong>FULL<br><em>COLOR.</em></strong>${chromaRig()}<div class="cm-now-foot"><span>22 SEP 2026<br>SIGNAL REMIX</span><b>0.1.0 ↗</b></div></div>`;}
